export const requireApproved=(context)=>{if(!context?.membership||context.membership.status!=='approved')throw Object.assign(new Error('Forbidden'),{status:403});};
export const requirePermission=(context,key)=>{requireApproved(context);if(!context.permissions.includes(key))throw Object.assign(new Error('Forbidden'),{status:403});};
export const requireOwnHousehold=(context,householdId)=>{requireApproved(context);if(!context.householdIds.includes(householdId)&&!context.permissions.includes('people.read'))throw Object.assign(new Error('Forbidden'),{status:403});};
export const buildAuthorizationContext=async(db,userId,organizationId)=>{const membership=await db.prepare('SELECT * FROM organization_memberships WHERE user_id=? AND organization_id=?').bind(userId,organizationId).first();if(!membership)return{membership:null,permissions:[],householdIds:[]};const permissions=(await db.prepare('SELECT DISTINCT rp.permission_key FROM membership_roles mr JOIN roles r ON r.id=mr.role_id JOIN role_permissions rp ON rp.role_id=r.id WHERE mr.membership_id=? AND mr.active=1 AND r.active=1 AND (mr.ends_at IS NULL OR mr.ends_at>CURRENT_TIMESTAMP)').bind(membership.id).all()).results.map(x=>x.permission_key);const householdIds=(await db.prepare('SELECT household_id FROM household_members WHERE user_id=? AND active=1').bind(userId).all()).results.map(x=>x.household_id);return{membership,permissions,householdIds};};
