import{createRemoteJWKSet,jwtVerify}from'jose';import{buildAuthorizationContext,requireApproved,requireOwnHousehold,requirePermission}from'./authorization.mjs';
const json=(data,status=200,headers={})=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json','cache-control':'no-store',...headers}});const id=p=>`${p}_${crypto.randomUUID()}`;const normalizeEmail=e=>String(e||'').trim().toLowerCase();
const identity=async(request,env)=>{const token=request.headers.get('cf-access-jwt-assertion');if(!token||!env.ACCESS_TEAM_DOMAIN||!env.ACCESS_AUD)throw Object.assign(new Error('Unauthenticated'),{status:401});const issuer=`${env.ACCESS_TEAM_DOMAIN.replace(/\/$/,'')}/cdn-cgi/access`;const{payload}=await jwtVerify(token,createRemoteJWKSet(new URL(`${issuer}/certs`)),{issuer,audience:env.ACCESS_AUD});if(!payload.sub||!payload.email)throw Object.assign(new Error('Unauthenticated'),{status:401});return{sub:String(payload.sub),email:normalizeEmail(payload.email),name:String(payload.name||payload.email),verified:true};};
const upsertUser=async(db,auth)=>{let row=await db.prepare('SELECT u.* FROM auth_identities ai JOIN users u ON u.id=ai.user_id WHERE ai.provider=? AND ai.provider_subject=?').bind('cloudflare-access',auth.sub).first();if(!row){row=await db.prepare('SELECT * FROM users WHERE primary_email=? AND email_verified=1').bind(auth.email).first();const userId=row?.id||id('usr');if(!row)await db.prepare('INSERT INTO users(id,primary_email,email_verified,display_name,account_status,onboarding_status) VALUES(?,?,?,?,?,?)').bind(userId,auth.email,1,auth.name,'active','new').run();await db.prepare('INSERT INTO auth_identities(id,user_id,provider,provider_subject,provider_email,verified,last_authenticated_at) VALUES(?,?,?,?,?,?,CURRENT_TIMESTAMP)').bind(id('aid'),userId,'cloudflare-access',auth.sub,auth.email,1).run();row=await db.prepare('SELECT * FROM users WHERE id=?').bind(userId).first();}await db.prepare('UPDATE users SET last_sign_in_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(row.id).run();return row;};
const audit=(db,actor,org,action,type,target,details={})=>db.prepare('INSERT INTO audit_events(id,organization_id,actor_user_id,action,target_type,target_id,details_json) VALUES(?,?,?,?,?,?,?)').bind(id('aud'),org,actor,action,type,target,JSON.stringify(details)).run();
export default{async fetch(request,env){try{const url=new URL(request.url);if(url.pathname==='/health')return json({ok:true,environment:env.ENVIRONMENT});const auth=await identity(request,env),user=await upsertUser(env.IDENTITY_DB,auth),org=url.searchParams.get('organization')||'org-pack-321',context=await buildAuthorizationContext(env.IDENTITY_DB,user.id,org);if(url.pathname==='/api/session')return json({user:{id:user.id,email:user.primary_email,displayName:user.display_name,onboardingStatus:user.onboarding_status},membership:context.membership&&{status:context.membership.status},permissions:context.permissions,destination:!context.membership?'/onboarding':context.membership.status!=='approved'?'/pending':context.permissions.includes('people.read')?'/my-day/leadership':'/my-day/parent'});if(url.pathname==='/api/onboarding'&&request.method==='POST'){const body=await request.json();let household=await env.IDENTITY_DB.prepare('SELECT h.* FROM households h JOIN household_members hm ON hm.household_id=h.id WHERE hm.user_id=? AND h.organization_id=?').bind(user.id,org).first();if(!household){const hid=id('hh');await env.IDENTITY_DB.batch([env.IDENTITY_DB.prepare('INSERT INTO households(id,organization_id,display_name,status) VALUES(?,?,?,?)').bind(hid,org,String(body.householdName||'New household').slice(0,80),'preliminary'),env.IDENTITY_DB.prepare('INSERT INTO household_members(id,household_id,user_id,relationship,primary_guardian) VALUES(?,?,?,?,1)').bind(id('hm'),hid,user.id,'guardian')]);household={id:hid};}await env.IDENTITY_DB.prepare("INSERT INTO onboarding_sessions(id,user_id,organization_id,household_id,current_step,state_json,status) VALUES(?,?,?,?,?,?, 'in_progress') ON CONFLICT(user_id,status) DO UPDATE SET current_step=excluded.current_step,state_json=excluded.state_json,updated_at=CURRENT_TIMESTAMP").bind(id('onb'),user.id,org,household.id,String(body.currentStep||'household'),JSON.stringify({householdName:body.householdName||''})).run();await env.IDENTITY_DB.prepare("UPDATE users SET onboarding_status='in_progress' WHERE id=?").bind(user.id).run();return json({ok:true,householdId:household.id},201);}if(url.pathname==='/api/access-requests'&&request.method==='POST'){const existing=await env.IDENTITY_DB.prepare("SELECT id FROM access_requests WHERE requester_user_id=? AND organization_id=? AND status='pending'").bind(user.id,org).first();if(existing)return json({requestId:existing.id,status:'pending'});const rid=id('req');await env.IDENTITY_DB.batch([env.IDENTITY_DB.prepare("INSERT INTO organization_memberships(id,user_id,organization_id,status) VALUES(?,?,?,'pending') ON CONFLICT(user_id,organization_id) DO UPDATE SET status='pending',updated_at=CURRENT_TIMESTAMP").bind(id('mem'),user.id,org),env.IDENTITY_DB.prepare("INSERT INTO access_requests(id,requester_user_id,organization_id,requested_relationship,reason,status) VALUES(?,?,?,?,?,'pending')").bind(rid,user.id,org,'parent_guardian','Pack access')]);await audit(env.IDENTITY_DB,user.id,org,'access.requested','access_request',rid);return json({requestId:rid,status:'pending'},201);}if(url.pathname==='/api/leadership/access-requests'){requirePermission(context,'access_requests.review');return json({requests:(await env.IDENTITY_DB.prepare("SELECT ar.id,ar.status,ar.created_at,u.display_name,u.primary_email FROM access_requests ar JOIN users u ON u.id=ar.requester_user_id WHERE ar.organization_id=? AND ar.status='pending'").bind(org).all()).results});}const approval=url.pathname.match(/^\/api\/leadership\/access-requests\/([^/]+)\/approve$/);if(approval&&request.method==='POST'){requirePermission(context,'access_requests.review');const req=await env.IDENTITY_DB.prepare("SELECT * FROM access_requests WHERE id=? AND organization_id=? AND status='pending'").bind(approval[1],org).first();if(!req)return json({error:'Not found'},404);const membership=await env.IDENTITY_DB.prepare('SELECT id FROM organization_memberships WHERE user_id=? AND organization_id=?').bind(req.requester_user_id,org).first();await env.IDENTITY_DB.batch([env.IDENTITY_DB.prepare("UPDATE access_requests SET status='approved',reviewed_by_user_id=?,reviewed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(user.id,req.id),env.IDENTITY_DB.prepare("UPDATE organization_memberships SET status='approved',approved_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(membership.id),env.IDENTITY_DB.prepare('INSERT INTO membership_roles(id,membership_id,role_id,assigned_by_user_id) VALUES(?,?,?,?)').bind(id('mr'),membership.id,'role-parent',user.id),env.IDENTITY_DB.prepare("UPDATE users SET onboarding_status='complete' WHERE id=?").bind(req.requester_user_id)]);await audit(env.IDENTITY_DB,user.id,org,'access.approved','access_request',req.id,{membershipId:membership.id});return json({ok:true});}const household=url.pathname.match(/^\/api\/households\/([^/]+)$/);if(household){requireOwnHousehold(context,household[1]);return json(await env.IDENTITY_DB.prepare('SELECT id,display_name,status FROM households WHERE id=? AND organization_id=?').bind(household[1],org).first());}if(url.pathname==='/api/organization'){requireApproved(context);return json(await env.IDENTITY_DB.prepare('SELECT id,display_name,program_year,founding_organization_mode FROM organizations WHERE id=?').bind(org).first());}return json({error:'Not found'},404);}catch(error){const status=error.status||500;if(status===500)console.error(JSON.stringify({event:'request_error',message:error.message}));return json({error:status===401?'Authentication required':status===403?'Forbidden':'Request failed'},status);}}};
